"""Patches the Android project generated by `flutter create` for Doctori.

Run from the app/ folder after `flutter create --platforms=android .`:
  python3 tool/patch_android.py
Idempotent: safe to run on every build.
"""
import pathlib
import re
import sys

APP_ID = "com.doctori.app"
LABEL = "دكتوري"

manifest = pathlib.Path("android/app/src/main/AndroidManifest.xml")
text = manifest.read_text(encoding="utf-8")

permissions = """    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION"/>
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION"/>
"""
if "android.permission.INTERNET" not in text:
    text = re.sub(r"(<manifest[^>]*>\s*)", lambda m: m.group(1) + permissions, text, count=1)

text = re.sub(r'android:label="[^"]*"', f'android:label="{LABEL}"', text, count=1)

deep_link = f"""            <intent-filter>
                <action android:name="android.intent.action.VIEW"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <category android:name="android.intent.category.BROWSABLE"/>
                <data android:scheme="{APP_ID}" android:host="login-callback"/>
            </intent-filter>
"""
if 'android:host="login-callback"' not in text:
    # Insert right after the MAIN/LAUNCHER intent-filter of MainActivity.
    text, n = re.subn(r"(<category android:name=\"android.intent.category.LAUNCHER\"\s*/>\s*</intent-filter>\s*)",
                      lambda m: m.group(1) + deep_link, text, count=1)
    if n != 1:
        sys.exit("Could not find the launcher intent-filter to add the deep link")

queries_extra = """        <intent>
            <action android:name="android.intent.action.VIEW"/>
            <data android:scheme="https"/>
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL"/>
            <data android:scheme="tel"/>
        </intent>
"""
if 'android:scheme="https"' not in text:
    if "<queries>" in text:
        text = text.replace("<queries>", "<queries>\n" + queries_extra, 1)
    else:
        text = text.replace("</manifest>", "    <queries>\n" + queries_extra + "    </queries>\n</manifest>", 1)

manifest.write_text(text, encoding="utf-8")

# applicationId → com.doctori.app (namespace stays as generated)
for name in ("android/app/build.gradle.kts", "android/app/build.gradle"):
    gradle = pathlib.Path(name)
    if gradle.exists():
        g = gradle.read_text(encoding="utf-8")
        g = re.sub(r'applicationId\s*=?\s*"[^"]+"',
                   lambda m: f'applicationId = "{APP_ID}"' if name.endswith(".kts") else f'applicationId "{APP_ID}"', g)
        gradle.write_text(g, encoding="utf-8")
        break
else:
    sys.exit("No app build.gradle found")

# ---------- Notifications (flutter_local_notifications) ----------
manifest_text = manifest.read_text(encoding="utf-8")
notif_perms = """    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED"/>
    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM"/>
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
    <uses-permission android:name="android.permission.VIBRATE"/>
"""
if "RECEIVE_BOOT_COMPLETED" not in manifest_text:
    manifest_text = manifest_text.replace(permissions, permissions + notif_perms, 1)
receivers = """        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON"/>
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ActionBroadcastReceiver" />
"""
if "ScheduledNotificationReceiver" not in manifest_text:
    manifest_text = manifest_text.replace("    </application>", receivers + "    </application>", 1)
if "ScheduledNotificationReceiver" not in manifest_text or "RECEIVE_BOOT_COMPLETED" not in manifest_text:
    sys.exit("Could not add notification setup to the manifest")
manifest.write_text(manifest_text, encoding="utf-8")

kts = pathlib.Path("android/app/build.gradle.kts")
if kts.exists():
    g = kts.read_text(encoding="utf-8")
    if "isCoreLibraryDesugaringEnabled" not in g:
        g, n = re.subn(r"compileOptions\s*\{", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", g, count=1)
        if n != 1:
            sys.exit("compileOptions block not found")
    if "multiDexEnabled" not in g:
        g = re.sub(r"defaultConfig\s*\{", "defaultConfig {\n        multiDexEnabled = true", g, count=1)
    if "desugar_jdk_libs" not in g:
        g += "\ndependencies {\n    coreLibraryDesugaring(\"com.android.tools:desugar_jdk_libs:2.1.4\")\n}\n"
    kts.write_text(g, encoding="utf-8")

# App icon (launcher + adaptive icon) generated from the Doctori logo.
import shutil
res_src = pathlib.Path("tool/android_res")
res_dst = pathlib.Path("android/app/src/main/res")
if res_src.exists():
    shutil.copytree(res_src, res_dst, dirs_exist_ok=True)

print("Android project patched for", APP_ID)
